# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of aten::_foreach_copy_ (in-place foreach copy).

For every pair (dst, src) the destination storage is preserved and elements of
src are cast to dst.dtype and written into dst.  All copies are performed by
Triton kernels; the host wrapper only reads tensor metadata (including
data_ptr), builds zero-copy views and launches kernels.

Launch strategies:
  * grouped  - contiguous pairs with identical float dtype and identical numel
    are bucketed and copied by ONE launch of an 8-slot kernel.  Slot addresses
    are passed as int64 scalars and cast to typed pointers inside the kernel, so
    there is exactly one copy code path.  After the first launch of a given
    specialization the compiled kernel is reused directly (skipping Triton's
    per-call argument binding / cache-key bookkeeping), which is where most of
    the fixed per-launch cost of this backend comes from.
  * per-pair - cross-dtype casts, broadcast/strided shapes, 1-byte dtypes,
    singleton buckets and buckets whose total bytes are large enough that
    pipelined per-pair launches hide their host cost behind device work.
"""

import torch
import triton
import triton.language as tl
from triton import knobs as _knobs
from triton.runtime import driver as _driver

_MAXDIM = 8
_MAXSLOTS = 8
_TARGET_BYTES = 8192
_MIN_BLOCK = 128
_MAX_BLOCK = 16384
# Above this many total read+write bytes a bucket is copied with pipelined
# per-pair launches instead of one grouped launch.
_MAX_GROUPED_BYTES = 450 * 1024 * 1024

# constexpr codes for the float dtypes eligible for the grouped path
_DT_CODE = {
    torch.float16: 0,
    torch.bfloat16: 1,
    torch.float32: 2,
}

# launch specialization -> compiled kernel for the direct launch path
_FAST_LAUNCH = {}
_FAST_FLAT = {}


def _direct_launch(cache, key, compiled, grid, vals):
    """Reuse an already compiled kernel, skipping Triton's per-call binder."""
    try:
        device = _driver.active.get_current_device()
        stream = _driver.active.get_current_stream(device)
        meta = None
        if compiled.launch_metadata is not None:
            meta = compiled.launch_metadata(grid, stream, *vals)
        compiled.foreach_copy_(
            grid[0],
            grid[1] if len(grid) > 1 else 1,
            1,
            stream,
            compiled.function,
            compiled.packed_metadata,
            meta,
            _knobs.runtime.launch_enter_hook,
            _knobs.runtime.launch_exit_hook,
            *vals,
        )
        return True
    except Exception:
        cache.pop(key, None)
        return False


@triton.jit
def _flat_copy_kernel(
    src_ptr,
    dst_ptr,
    n,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
    TO_BOOL: tl.constexpr,
    IDX64: tl.constexpr,
):
    pid = tl.program_id(0)
    if IDX64:
        offs = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    else:
        offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        v = tl.load(src_ptr + offs)
        if TO_BOOL:
            tl.store(dst_ptr + offs, (v != 0).to(tl.uint8))
        else:
            tl.store(dst_ptr + offs, v.to(dst_ptr.dtype.element_ty))
    else:
        m = offs < n
        v = tl.load(src_ptr + offs, mask=m)
        if TO_BOOL:
            tl.store(dst_ptr + offs, (v != 0).to(tl.uint8), mask=m)
        else:
            tl.store(dst_ptr + offs, v.to(dst_ptr.dtype.element_ty), mask=m)


@triton.jit
def _copy_addr_tile(sa, da, offs, mask, DT: tl.constexpr, EVEN: tl.constexpr):
    if DT == 0:
        sp = sa.to(tl.pointer_type(tl.float16))
        dp = da.to(tl.pointer_type(tl.float16))
    elif DT == 1:
        sp = sa.to(tl.pointer_type(tl.bfloat16))
        dp = da.to(tl.pointer_type(tl.bfloat16))
    else:
        sp = sa.to(tl.pointer_type(tl.float32))
        dp = da.to(tl.pointer_type(tl.float32))
    if EVEN:
        tl.store(dp + offs, tl.load(sp + offs))
    else:
        tl.store(dp + offs, tl.load(sp + offs, mask=mask), mask=mask)


@triton.jit
def _group_copy_kernel(
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    n,
    BLOCK: tl.constexpr,
    IDX64: tl.constexpr,
    EVEN: tl.constexpr,
    DT: tl.constexpr,
):
    slot = tl.program_id(1)
    pid = tl.program_id(0)
    if IDX64:
        offs = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    else:
        offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n

    sa = s0
    da = d0
    if slot == 1:
        sa = s1
        da = d1
    elif slot == 2:
        sa = s2
        da = d2
    elif slot == 3:
        sa = s3
        da = d3
    elif slot == 4:
        sa = s4
        da = d4
    elif slot == 5:
        sa = s5
        da = d5
    elif slot == 6:
        sa = s6
        da = d6
    elif slot == 7:
        sa = s7
        da = d7

    _copy_addr_tile(sa, da, offs, mask, DT, EVEN)


@triton.jit
def _strided_copy_kernel(
    src_ptr,
    dst_ptr,
    n,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    ss0,
    ss1,
    ss2,
    ss3,
    ss4,
    ss5,
    ss6,
    ss7,
    ds0,
    ds1,
    ds2,
    ds3,
    ds4,
    ds5,
    ds6,
    ds7,
    BLOCK: tl.constexpr,
    TO_BOOL: tl.constexpr,
    FROM_BOOL: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = (pid * BLOCK + tl.arange(0, BLOCK)).to(tl.int64)
    rem = offs
    so = tl.zeros([BLOCK], tl.int64)
    do = tl.zeros([BLOCK], tl.int64)

    i0 = rem % s0
    rem = rem // s0
    so += i0 * ss0
    do += i0 * ds0
    i1 = rem % s1
    rem = rem // s1
    so += i1 * ss1
    do += i1 * ds1
    i2 = rem % s2
    rem = rem // s2
    so += i2 * ss2
    do += i2 * ds2
    i3 = rem % s3
    rem = rem // s3
    so += i3 * ss3
    do += i3 * ds3
    i4 = rem % s4
    rem = rem // s4
    so += i4 * ss4
    do += i4 * ds4
    i5 = rem % s5
    rem = rem // s5
    so += i5 * ss5
    do += i5 * ds5
    i6 = rem % s6
    rem = rem // s6
    so += i6 * ss6
    do += i6 * ds6
    i7 = rem % s7
    so += i7 * ss7
    do += i7 * ds7

    m = offs < n
    v = tl.load(src_ptr + so, mask=m)
    if FROM_BOOL:
        v = v.to(tl.uint8)
    if TO_BOOL:
        tl.store(dst_ptr + do, (v != 0).to(tl.uint8), mask=m)
    else:
        tl.store(dst_ptr + do, v.to(dst_ptr.dtype.element_ty), mask=m)


def _pick_block(n, itemsize):
    b = _TARGET_BYTES // max(int(itemsize), 1)
    if b < _MIN_BLOCK:
        b = _MIN_BLOCK
    if b > _MAX_BLOCK:
        b = _MAX_BLOCK
    if b > n:
        b = triton.next_power_of_2(n)
        if b < _MIN_BLOCK:
            b = _MIN_BLOCK
    return b


def _byte_view_for_bool(t):
    """Zero-copy uint8 view for bool tensors when the layout allows it."""
    if t.dtype is not torch.bool:
        return t, False
    try:
        return t.view(torch.uint8), True
    except Exception:
        return t, False


def _flat_copy(dst, src, n):
    dst_arg, _ = _byte_view_for_bool(dst)
    src_arg, src_is_byte = _byte_view_for_bool(src)
    same_byte_dtype = dst.dtype is src.dtype and dst.element_size() == 1
    if same_byte_dtype:
        dst_arg = dst.view(torch.uint8)
        src_arg = src.view(torch.uint8)
    to_bool = dst.dtype is torch.bool
    if dst.dtype is src.dtype and dst.element_size() == 2 and (n % 2) == 0:
        # Bit-exact copy of 2-byte elements as 4-byte words: fewer vector
        # instructions per byte on the AI vector cores.
        try:
            _flat_launch(
                src_arg.view(torch.int32), dst_arg.view(torch.int32), n // 2, False
            )
            return
        except Exception:
            pass
    _flat_launch(src_arg, dst_arg, n, to_bool)
    _ = src_is_byte


def _flat_launch(src_arg, dst_arg, n, to_bool):
    itemsize = max(dst_arg.element_size(), src_arg.element_size())
    block = _pick_block(n, itemsize)
    even = (n % block) == 0
    idx64 = n >= (1 << 31)
    grid = (triton.cdiv(n, block),)
    key = (
        src_arg.dtype,
        dst_arg.dtype,
        block,
        even,
        to_bool,
        idx64,
        n == 1,
        n % 16,
    )
    s_addr = src_arg.data_ptr()
    d_addr = dst_arg.data_ptr()
    compiled = _FAST_FLAT.get(key)
    if compiled is not None and not ((s_addr | d_addr) & 15):
        vals = (s_addr, d_addr, n, block, even, to_bool, idx64)
        if _direct_launch(_FAST_FLAT, key, compiled, grid, vals):
            return
    kernel = _flat_copy_kernel[grid](
        src_arg,
        dst_arg,
        n,
        BLOCK=block,
        EVEN=even,
        TO_BOOL=to_bool,
        IDX64=idx64,
    )
    if not ((s_addr | d_addr) & 15):
        _FAST_FLAT[key] = kernel


def _grouped_flat_copy(pairs, n, dt_code, itemsize):
    """One launch for up to _MAXSLOTS same-dtype, same-numel contiguous pairs."""
    block = _pick_block(n, itemsize)
    idx64 = n >= (1 << 31)
    even = (n % block) == 0
    ntiles = triton.cdiv(n, block)
    fast_key = (dt_code, block, idx64, even, n == 1, n % 16, ntiles == 1, ntiles % 16)
    for start in range(0, len(pairs), _MAXSLOTS):
        chunk = pairs[start : start + _MAXSLOTS]
        dsts = [p[0].data_ptr() for p in chunk]
        srcs = [p[1].data_ptr() for p in chunk]
        k = len(chunk)
        while len(dsts) < _MAXSLOTS:
            dsts.append(dsts[0])
            srcs.append(srcs[0])
        grid = (ntiles, k)
        addrs = srcs + dsts
        compiled = _FAST_LAUNCH.get(fast_key)
        launched = False
        if compiled is not None and not any(a & 15 for a in addrs):
            # Same specialization as the compiled kernel: reuse it directly.
            vals = (
                srcs[0],
                srcs[1],
                srcs[2],
                srcs[3],
                srcs[4],
                srcs[5],
                srcs[6],
                srcs[7],
                dsts[0],
                dsts[1],
                dsts[2],
                dsts[3],
                dsts[4],
                dsts[5],
                dsts[6],
                dsts[7],
                n,
                block,
                idx64,
                even,
                dt_code,
            )
            launched = _direct_launch(_FAST_LAUNCH, fast_key, compiled, grid, vals)
        if not launched:
            kernel = _group_copy_kernel[grid](
                srcs[0],
                srcs[1],
                srcs[2],
                srcs[3],
                srcs[4],
                srcs[5],
                srcs[6],
                srcs[7],
                dsts[0],
                dsts[1],
                dsts[2],
                dsts[3],
                dsts[4],
                dsts[5],
                dsts[6],
                dsts[7],
                n,
                BLOCK=block,
                IDX64=idx64,
                EVEN=even,
                DT=dt_code,
            )
            if not any(a & 15 for a in addrs):
                _FAST_LAUNCH[fast_key] = kernel


def _prep_strided(dst, src):
    """Right-aligned broadcast index description collapsed to <= 8 dims."""
    dshape = list(dst.shape)
    dstride = list(dst.stride())
    sshape = list(src.shape)
    sstride = list(src.stride())
    ndim = len(dshape)
    pad = ndim - len(sshape)
    if pad < 0:
        raise RuntimeError(
            "The size of tensor a ({}) must match the size of tensor b ({}) "
            "at non-singleton dimension {}".format(ndim, len(sshape), 0)
        )
    sshape = [1] * pad + sshape
    sstride = [0] * pad + sstride
    for d in range(ndim):
        if sshape[d] == dshape[d]:
            continue
        if sshape[d] == 1:
            sstride[d] = 0
        else:
            raise RuntimeError(
                "The size of tensor a ({}) must match the size of tensor b ({}) "
                "at non-singleton dimension {}".format(dshape[d], sshape[d], d)
            )
    sizes, dsts, srcs = [], [], []
    for d in range(ndim):
        if dshape[d] != 1:
            sizes.append(dshape[d])
            dsts.append(dstride[d])
            srcs.append(sstride[d])
    # merge adjacent dims that are contiguous in both tensors
    i = len(sizes) - 1
    while i > 0:
        if dsts[i - 1] == dsts[i] * sizes[i] and srcs[i - 1] == srcs[i] * sizes[i]:
            sizes[i - 1] = sizes[i - 1] * sizes[i]
            dsts[i - 1] = dsts[i]
            srcs[i - 1] = srcs[i]
            del sizes[i]
            del dsts[i]
            del srcs[i]
        i -= 1
    return sizes, dsts, srcs


def _strided_copy(dst, src):
    sizes, dsts, srcs = _prep_strided(dst, src)
    if len(sizes) > _MAXDIM:
        # Fall back to slicing the outermost dimension (metadata-only views).
        for i in range(dst.shape[0]):
            if src.dim() == dst.dim():
                _copy_pair(
                    dst.select(0, i), src.select(0, 0 if src.shape[0] == 1 else i)
                )
            else:
                _copy_pair(dst.select(0, i), src)
        return
    pad = _MAXDIM - len(sizes)
    sz = [1] * pad + sizes
    dstr = [0] * pad + dsts
    sstr = [0] * pad + srcs

    dst_arg, _ = _byte_view_for_bool(dst)
    src_arg, src_is_byte = _byte_view_for_bool(src)
    to_bool = dst.dtype is torch.bool
    from_bool = (src.dtype is torch.bool) and not src_is_byte

    n = dst.numel()
    itemsize = max(dst.element_size(), src.element_size())
    block = _pick_block(n, itemsize)
    grid = (triton.cdiv(n, block),)
    _strided_copy_kernel[grid](
        src_arg,
        dst_arg,
        n,
        sz[0],
        sz[1],
        sz[2],
        sz[3],
        sz[4],
        sz[5],
        sz[6],
        sz[7],
        sstr[0],
        sstr[1],
        sstr[2],
        sstr[3],
        sstr[4],
        sstr[5],
        sstr[6],
        sstr[7],
        dstr[0],
        dstr[1],
        dstr[2],
        dstr[3],
        dstr[4],
        dstr[5],
        dstr[6],
        dstr[7],
        BLOCK=block,
        TO_BOOL=to_bool,
        FROM_BOOL=from_bool,
    )


def _copy_pair(dst, src):
    if dst is src:
        return
    n = dst.numel()
    if n == 0:
        return
    if dst.shape == src.shape and dst.is_contiguous() and src.is_contiguous():
        _flat_copy(dst, src, n)
        return
    _strided_copy(dst, src)


def foreach_copy_(self, src, non_blocking=False):
    if len(self) != len(src):
        raise RuntimeError(
            "Tensor lists must have the same number of tensors, got {} and {}".format(
                len(self), len(src)
            )
        )
    groups = {}
    for dst, s in zip(self, src):
        if dst is s:
            continue
        n = dst.numel()
        if n == 0:
            continue
        code = _DT_CODE.get(dst.dtype) if dst.dtype is s.dtype else None
        if (
            code is not None
            and dst.shape == s.shape
            and dst.is_contiguous()
            and s.is_contiguous()
        ):
            groups.setdefault((code, n, dst.element_size()), []).append((dst, s))
        else:
            _copy_pair(dst, s)
    for (code, n, itemsize), pairs in groups.items():
        if len(pairs) > 1 and len(pairs) * 2 * n * itemsize > _MAX_GROUPED_BYTES:
            # Large buckets: pipelined per-pair launches hide their host cost
            # behind device work, which one grouped launch cannot do.
            for dst, s in pairs:
                _flat_copy(dst, s, n)
        elif len(pairs) == 1:
            _flat_copy(pairs[0][0], pairs[0][1], n)
        else:
            _grouped_flat_copy(pairs, n, code, itemsize)
    return None
